import React, { useEffect, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import Button from "../components/common/Button";
import { useUI } from "../context/UIContext";
import styles from "../Result.module.css";
import { saveToSheet } from "../components/utils/googleSheetLogger";

// 🚀 關鍵改動：從資料模組統一引入 DCS 相關資料 (路徑請根據您實際專案調整)
import { DCS_QUESTIONS, DCS_OPTIONS, DCS_CITATION } from "../constants/dcs";

const Result = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const { setHeroData, allAnswers } = useUI();
  const { finalData } = location.state || {};

  // 狀態管理
  const [isFlowModalOpen, setIsFlowModalOpen] = useState(false);
  const [isSurveyModalOpen, setIsSurveyModalOpen] = useState(false);
  const [isSurveyCompleted, setIsSurveyCompleted] = useState(false);

  // DCS 問卷內部分步狀態
  const [currentDcsIndex, setCurrentDcsIndex] = useState(0);
  const [dcsAnswers, setDcsAnswers] = useState({});

  const flowCharts = {
    BCT: "https://sdm-5cbs.onrender.com/assets/images/bct.png",
    SM: "https://sdm-5cbs.onrender.com/assets/images/sm.png",
  };

  useEffect(() => {
    if (!finalData) return;

    setHeroData({
      imageUrl:
        "https://web-production-fbb7b.up.railway.app/static/helperinside.png",
      title: "評估結果建議",
      description: `${allAnswers.userName || "您"}好！經過剛剛的模擬體驗，我為您整理出的建議方案是：【${finalData.title}】。您可以點擊下方查看預計治療流程，或直接開始填寫最後的評估問卷。`,
    });
  }, [setHeroData, finalData, allAnswers.userName]);

  // 送出最終完整資料
  const submitAllDataToSheet = async (finalDcsAnswers) => {
    try {
      const logData = {
        date: new Date().toLocaleDateString(),
        userName: allAnswers.userName,
        birthDate: allAnswers.birthday || allAnswers.birthDate,
        selectedTopic: allAnswers.selectedTopic,
        details: JSON.stringify(allAnswers.answers),
        finalResult: finalData.title,
        dcsScore: JSON.stringify(finalDcsAnswers), // 完美整合 16 題問卷結果
      };
      await saveToSheet(logData);
    } catch (error) {
      console.error("資料同步失敗", error);
    }
  };

  if (!finalData) {
    return (
      <div className={styles.emptyState}>
        <h3>尚未完成評估</h3>
        <p>請回問卷頁面重新操作。</p>
        <Button onClick={() => navigate("/selection")}>返回主選單</Button>
      </div>
    );
  }

  let displayType = finalData.type;
  if (!displayType && finalData.title) {
    if (finalData.title.includes("部分")) displayType = "BCT";
    else if (finalData.title.includes("全乳房")) displayType = "SM";
  }
  const chartUrl = flowCharts[displayType];

  // 處理 DCS 問卷點選答案
  const handleDcsSelect = (value) => {
    const currentQuestion = DCS_QUESTIONS[currentDcsIndex];
    const updatedAnswers = { ...dcsAnswers, [currentQuestion.id]: value };
    setDcsAnswers(updatedAnswers);

    if (currentDcsIndex < DCS_QUESTIONS.length - 1) {
      setCurrentDcsIndex(currentDcsIndex + 1);
    } else {
      setIsSurveyCompleted(true);
      setIsSurveyModalOpen(false);
      submitAllDataToSheet(updatedAnswers);
    }
  };

  return (
    <div className={styles.container}>
      {/* 核心建議方案 */}
      <div className={styles.resultCard}>
        <h2 className={styles.resultTitle}>{finalData.title}</h2>
        <hr className={styles.divider} />
        <div
          className={styles.description}
          dangerouslySetInnerHTML={{ __html: finalData.description }}
        />
      </div>

      {/* 互動功能區塊 */}
      <div
        className={styles.interactiveGroup}
        style={{ width: "100%", maxWidth: "480px", margin: "20px 0" }}
      >
        {/* 1. 查看流程圖按鈕 */}
        {chartUrl && (
          <Button
            variant="outline"
            onClick={() => setIsFlowModalOpen(true)}
            style={{ width: "100%", marginBottom: "15px" }}
          >
            🔍 查看您的預計治療流程
          </Button>
        )}

        {/* 2. 決策衝突問卷引導區塊 */}
        <div
          className={styles.surveySection}
          style={{
            padding: "20px",
            backgroundColor: isSurveyCompleted ? "#f6ffed" : "#fff7e6",
            border: `1px solid ${isSurveyCompleted ? "#b7eb8f" : "#ffd591"}`,
            borderRadius: "12px",
            textAlign: "center",
          }}
        >
          <p
            style={{
              fontWeight: "bold",
              color: isSurveyCompleted ? "#52c41a" : "#d46b08",
              fontSize: "1.1rem",
              margin: "0 0 10px 0",
            }}
          >
            {isSurveyCompleted
              ? "✅ 感謝您的填寫！醫療團隊已收到您的回饋。"
              : "最後一步：請填寫決策評估問卷"}
          </p>
          {!isSurveyCompleted && (
            <Button
              onClick={() => setIsSurveyModalOpen(true)}
              style={{ backgroundColor: "#fa8c16", color: "#fff" }}
            >
              點此開始互動問卷
            </Button>
          )}
        </div>
      </div>

      {/* 底部導覽：完成按鈕 */}
      <div
        className={styles.buttonGroup}
        style={{ width: "100%", maxWidth: "480px" }}
      >
        <Button
          style={{ width: "100%" }}
          onClick={() => navigate("/selection")}
          isDisabled={!isSurveyCompleted}
        >
          {isSurveyCompleted ? "完成並回首頁" : "請先完成上方問卷以解鎖結束"}
        </Button>
      </div>

      {/* ==================== 彈窗 1：治療流程與列印 Modal ==================== */}
      {isFlowModalOpen && (
        <div
          className={styles.modalOverlay}
          onClick={() => setIsFlowModalOpen(false)}
          style={modalOverlayStyle}
        >
          <div
            className={styles.modalContent}
            onClick={(e) => e.stopPropagation()}
            style={modalContentStyle}
          >
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                marginBottom: "15px",
              }}
            >
              <h3>您的預計治療流程</h3>
              <button
                onClick={() => setIsFlowModalOpen(false)}
                style={closeButtonStyle}
              >
                ✕
              </button>
            </div>
            <div
              style={{
                maxHeight: "60vh",
                overflowY: "auto",
                textAlign: "center",
              }}
            >
              <img
                src={chartUrl}
                alt="治療流程圖"
                style={{ width: "100%", height: "auto" }}
              />
            </div>
            <div style={{ marginTop: "15px", display: "flex", gap: "10px" }}>
              <Button style={{ flex: 1 }} onClick={() => window.print()}>
                🖨️ 列印 / 儲存 PDF
              </Button>
              <Button
                variant="outline"
                style={{ flex: 1 }}
                onClick={() => setIsFlowModalOpen(false)}
              >
                關閉視窗
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* ==================== 彈窗 2：16 題 DCS 滿版互動問卷 Modal ==================== */}
      {isSurveyModalOpen && (
        <div className={styles.modalOverlay} style={fullscreenOverlayStyle}>
          <div className={styles.modalContent} style={fullscreenContentStyle}>
            {/* 頂部學術引用規範（使用引入的 DCS_CITATION） */}
            <div style={citationHeaderStyle}>
              <span>{DCS_CITATION.title}</span>
              <small
                style={{
                  color: "#8c8c8c",
                  display: "block",
                  fontSize: "0.75rem",
                  marginTop: "4px",
                }}
              >
                {DCS_CITATION.source}
              </small>
            </div>

            {/* 進度條 */}
            <div style={progressContainerStyle}>
              <div
                style={{
                  ...progressBarStyle,
                  width: `${((currentDcsIndex + 1) / DCS_QUESTIONS.length) * 100}%`,
                }}
              ></div>
              <span style={{ fontSize: "0.85rem", color: "#595959" }}>
                題組：{currentDcsIndex + 1} / {DCS_QUESTIONS.length}
              </span>
            </div>

            {/* 題目核心區 */}
            <div style={questionZoneStyle}>
              <p
                style={{
                  fontSize: "1.15rem",
                  fontWeight: "bold",
                  lineHeight: "1.6",
                  color: "#262626",
                }}
              >
                {DCS_QUESTIONS[currentDcsIndex].text}
              </p>
            </div>

            {/* 答案點選區 */}
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                gap: "12px",
                width: "100%",
              }}
            >
              {DCS_OPTIONS.map((opt) => (
                <button
                  key={opt.value}
                  onClick={() => handleDcsSelect(opt.value)}
                  style={dcsOptionButtonStyle}
                >
                  {opt.label}
                </button>
              ))}
            </div>

            {/* 上一題 */}
            {currentDcsIndex > 0 && (
              <button
                onClick={() => setCurrentDcsIndex(currentDcsIndex - 1)}
                style={{
                  marginTop: "20px",
                  background: "none",
                  border: "none",
                  color: "#8c8c8c",
                  cursor: "pointer",
                  textDecoration: "underline",
                }}
              >
                返回上一題
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

// --- 精簡的行內樣式 ---
const modalOverlayStyle = {
  position: "fixed",
  top: 0,
  left: 0,
  right: 0,
  bottom: 0,
  backgroundColor: "rgba(0,0,0,0.5)",
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  zIndex: 1000,
  padding: "20px",
};
const modalContentStyle = {
  backgroundColor: "#fff",
  padding: "20px",
  borderRadius: "16px",
  width: "100%",
  maxWidth: "500px",
  boxShadow: "0 4px 12px rgba(0,0,0,0.15)",
};
const closeButtonStyle = {
  background: "none",
  border: "none",
  fontSize: "1.2rem",
  cursor: "pointer",
  marginLeft: "auto",
};

const fullscreenOverlayStyle = {
  position: "fixed",
  top: 0,
  left: 0,
  right: 0,
  bottom: 0,
  backgroundColor: "#fff5f7",
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  zIndex: 2000,
};
const fullscreenContentStyle = {
  width: "100%",
  maxWidth: "480px",
  height: "100%",
  padding: "40px 24px",
  display: "flex",
  flexDirection: "column",
  alignItems: "center",
  justifyContent: "start",
  boxSizing: "border-box",
  overflowY: "auto",
};
const citationHeaderStyle = {
  textAlign: "center",
  borderBottom: "1px solid #ffe3e8",
  paddingBottom: "12px",
  marginBottom: "20px",
  width: "100%",
  fontWeight: "bold",
  color: "#c41d7f",
};
const progressContainerStyle = {
  width: "100%",
  display: "flex",
  justifyContent: "space-between",
  alignItems: "center",
  marginBottom: "30px",
};
const progressBarStyle = {
  height: "6px",
  backgroundColor: "#ffadd2",
  borderRadius: "3px",
  transition: "width 0.3s",
};
const questionZoneStyle = {
  flex: 1,
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  textAlign: "center",
  padding: "20px 0",
  marginBottom: "20px",
};
const dcsOptionButtonStyle = {
  width: "100%",
  padding: "16px",
  backgroundColor: "#fff",
  border: "2px solid #ffadd2",
  borderRadius: "12px",
  fontSize: "1.05rem",
  fontWeight: "600",
  color: "#c41d7f",
  cursor: "pointer",
  transition: "all 0.2s",
  textAlign: "center",
  boxShadow: "0 2px 6px rgba(244,162,180,0.15)",
};

export default Result;
